{
  "company": "CRONUS International Ltd.",
  "messageType": "Sales.OrderConfirmation.Send",
  "status": "Success",
  "contract": "json",
  "format": "chapters",
  "catalogue": {
    "name": "Sales.OrderConfirmation.Send",
    "isEnabled": true,
    "filterTableNo": 36,
    "description": "Sendir sölupöntunarstaðfestingu með forstillingu skjalasendingar sem leyst er upp.",
    "selectionDescription": "Senda viðskiptamanni sölupöntunarstaðfestingu með forstillingu skjalasendingar, eins og aðgerðin Senda á sölupöntuninni. Óafturkræft. Til að fá PDF án sendingar, notaðu Sales.OrderConfirmation.Pdf þegar sú tegund er tiltæk.",
    "messageDirection": "Inbound",
    "keywords": [
      "senda pöntunarstaðfestingu",
      "senda pöntunarstaðfestingu í tölvupósti",
      "senda sölupöntun til viðskiptamanns",
      "afhending pöntunarstaðfestingar",
      "tölvupóstur með staðfestingu",
      "afhenda pöntunarstaðfestinguna"
    ],
    "chargeable": true
  },
  "chapters": {
    "envelope": {
      "strict": {
        "type": "boolean",
        "required": false,
        "default": false,
        "description": "Optional root Boolean, default false. When true, unknown data keys are refused before execution with UnknownParameter. Do not place this option inside data."
      },
      "subject": {
        "use": "optional",
        "forms": [
          "guid",
          "code"
        ],
        "description": "Sales order number, or its SystemId."
      },
      "dataRequired": false,
      "version": "1.0",
      "contentType": "text/json"
    },
    "target": [
      {
        "source": "subject",
        "form": "guid|code",
        "description": "The document number, or its SystemId. A GUID is the SystemId. Anything else is the number."
      },
      {
        "source": "data.documentNo",
        "form": "code",
        "description": "Document number. Optional when subject or orderNo is sent."
      },
      {
        "source": "data.orderNo",
        "form": "code",
        "description": "Document number. Same document as documentNo when both are sent."
      },
      {
        "source": "data.documentId",
        "form": "guid",
        "description": "SystemId of the document."
      },
      {
        "source": "data.orderId",
        "form": "guid",
        "description": "SystemId of the document. Same document as documentId when both are sent."
      }
    ],
    "parameters": [
      {
        "name": "documentNo",
        "type": "string",
        "required": false,
        "description": "Document number. A GUID belongs in documentId or subject. At most 20 characters."
      },
      {
        "name": "orderNo",
        "type": "string",
        "required": false,
        "description": "Same as documentNo. When both are sent they must name the same document."
      },
      {
        "name": "documentId",
        "type": "string",
        "required": false,
        "description": "SystemId (GUID) of the document."
      },
      {
        "name": "orderId",
        "type": "string",
        "required": false,
        "description": "Same as documentId. When both are sent they must name the same document."
      },
      {
        "name": "documentSendingProfile",
        "type": "string",
        "required": false,
        "description": "Code of the Document Sending Profile for this call only, at most 20 characters. A longer value is refused (InvalidParameterFormat), never cut. Must exist, must not save to disk and must not prompt for e-mail settings. Left out: the vendor or customer profile, then the profile marked Default."
      },
      {
        "name": "expectedCount",
        "type": "integer",
        "required": false,
        "description": "Always checked when sent. Required only when Require Confirmation for Irreversible Messages is enabled in Bifrost Setup (on by default; an administrator can turn it off per company). When enabled, call without expectedCount to preview the count."
      }
    ],
    "response": {
      "contentType": "text/json",
      "fields": [
        {
          "name": "status",
          "type": "string",
          "description": "Success."
        },
        {
          "name": "documentType",
          "type": "string",
          "description": "Always SalesOrderConfirmation."
        },
        {
          "name": "documentNo",
          "type": "string",
          "description": "No. of the document."
        },
        {
          "name": "documentId",
          "type": "string",
          "description": "SystemId of the document (GUID, no braces)."
        },
        {
          "name": "customerNo",
          "type": "string",
          "description": "Party number (Customer)."
        },
        {
          "name": "customerName",
          "type": "string",
          "description": "Party name (Customer)."
        },
        {
          "name": "documentSendingProfileCode",
          "type": "string",
          "description": "Code of the Document Sending Profile that was used."
        },
        {
          "name": "documentSendingProfileSource",
          "type": "string",
          "description": "Where the profile came from: Request, the party profile, or Default.",
          "allowed": [
            "Request",
            "Customer",
            "Default"
          ]
        },
        {
          "name": "message",
          "type": "string",
          "description": "Document sent successfully."
        }
      ]
    },
    "errors": [
      {
        "code": "PermissionDenied",
        "error": "Read permission denied.",
        "when": "The caller has no read permission on Sales Header.",
        "fix": "Ask an administrator to grant read access to Sales Header."
      },
      {
        "code": "MissingParameter",
        "error": "Send the document number or SystemId.",
        "when": "subject and the document keys were all left out.",
        "fix": "Put the number in subject or data.documentNo, or the SystemId in subject or data.documentId."
      },
      {
        "code": "RecordNotFound",
        "error": "Document not found (Sales order).",
        "when": "The number or SystemId does not identify an existing document of this type (Sales order).",
        "fix": "Send the document number or SystemId of an existing document of this type."
      },
      {
        "code": "InvalidParameterFormat",
        "error": "Parameter \"documentSendingProfile\" is not a JSON string or is longer than 20 characters.",
        "when": "documentSendingProfile was sent as an object or an array, or is longer than 20 characters. A longer code is refused, never cut.",
        "fix": "Send the value as a JSON string of at most 20 characters."
      },
      {
        "code": "InvalidParameterFormat",
        "error": "documentId is not a GUID.",
        "when": "documentId or the id key is not a GUID.",
        "fix": "Send the SystemId as a GUID, or send the document number."
      },
      {
        "code": "ConflictingIdentifiers",
        "error": "The identifiers name different documents.",
        "when": "Two keys were sent and they do not name the same document. Nothing was sent.",
        "fix": "Send one document number or one SystemId."
      },
      {
        "code": "RecordNotFound",
        "error": "Document Sending Profile \"{code}\" not found.",
        "when": "documentSendingProfile names a profile that does not exist. Nothing was sent.",
        "fix": "Send the Code of an existing Document Sending Profile, or leave the key out."
      },
      {
        "code": "PreconditionFailed",
        "error": "The party profile does not exist, or no profile resolves.",
        "when": "No documentSendingProfile was sent and the customer or vendor profile is missing or points at a deleted profile, and no profile is marked Default.",
        "fix": "Send documentSendingProfile, fix the party profile, or mark one profile Default."
      },
      {
        "code": "PreconditionFailed",
        "error": "Document Sending Profile \"{code}\" saves the document to disk, which needs a client.",
        "when": "The resolved profile has a Disk channel. Nothing was sent.",
        "fix": "Send a profile that has no Disk channel."
      },
      {
        "code": "PreconditionFailed",
        "error": "The resolved profile prompts for e-mail settings.",
        "when": "E-Mail is Yes (Prompt for Settings). Nothing was sent.",
        "fix": "Pass a profile with E-Mail set to Yes (Use Default Settings)."
      },
      {
        "code": "PreconditionFailed",
        "error": "The customer or vendor has no e-mail address for the profile.",
        "when": "The resolved profile sends e-mail and the party has no e-mail address. Nothing was sent.",
        "fix": "Set the e-mail address or select a profile that does not send e-mail."
      },
      {
        "code": "BusinessCentralError",
        "error": "Business Central's own error text",
        "when": "Business Central refuses to send, for example no e-mail account or no report for the Report Selection usage.",
        "fix": "Read the text. Check the document before sending again: a channel may already have delivered it."
      }
    ],
    "effect": {
      "effect": "irreversible",
      "idempotent": false,
      "preconditions": [],
      "changes": "Sends the sales order confirmation with the resolved profile, as the Send action does. It cannot be rolled back with the caller, so Orchestrator's Omit Commit guard refuses it in a playbook chain that must roll back together. Needs expectedCount only when enabled in Bifrost Setup (on by default; an administrator can turn it off per company); always checked when sent. When enabled, call without it to see the preview."
    },
    "metering": {
      "chargeable": true,
      "chargedAs": "message"
    },
    "related": [
      {
        "name": "Purchase.Order.Send",
        "useInsteadWhen": "The document is a purchase order."
      },
      {
        "name": "Sales.Quote.Send",
        "useInsteadWhen": "The document is a sales quote."
      },
      {
        "name": "Data.Records.Get",
        "useInsteadWhen": "You want to read the document afterwards without sending it again."
      }
    ],
    "workflow": {
      "steps": [
        {
          "messageType": "Data.Records.Get",
          "purpose": "Read the document and take its number or SystemId."
        },
        {
          "messageType": "Sales.OrderConfirmation.Send",
          "purpose": "Send that sales order confirmation."
        }
      ]
    },
    "examples": [
      {
        "title": "Send with an explicit profile",
        "request": {
          "type": "Sales.OrderConfirmation.Send",
          "data": {
            "orderNo": "101001",
            "documentSendingProfile": "EMAIL"
          }
        },
        "response": {
          "status": "Success",
          "documentNo": "101001",
          "documentSendingProfileCode": "EMAIL",
          "documentSendingProfileSource": "Request",
          "message": "Document sent successfully."
        }
      },
      {
        "title": "Unknown document",
        "request": {
          "type": "Sales.OrderConfirmation.Send",
          "data": {
            "documentNo": "DOES-NOT-EXIST"
          }
        },
        "response": {
          "status": "Error",
          "code": "RecordNotFound",
          "parameter": "documentNo",
          "nextStep": "Send the document number or SystemId of an existing document of this type."
        }
      }
    ],
    "overview": "Sends one document (sales order confirmation) through a Document Sending Profile: the request profile, otherwise the party profile, otherwise the Default profile. Irreversible. Missing documents, profiles or required e-mail addresses are refused before sending. Worker tests must mock the send; Disk profiles need a client and are refused. The matching PDF type is Sales.OrderConfirmation.Pdf.",
    "notes": "Success means every profile channel ran without error, not confirmed receipt. A retry sends again. subject and data identifiers must agree; a GUID is the SystemId, otherwise the number. Conflicting keys return ConflictingIdentifiers. Profile codes are compared in upper case. Disk or prompted e-mail profiles are refused before sending. The matching PDF type Sales.OrderConfirmation.Pdf is a separate dependency for callers wanting a file; this send does not call it."
  },
  "conventions": "## Errors and warnings\r\nAn error response has `status` = `Error`, a stable `code`, the `error` text and, when they apply, `parameter` (the request parameter concerned, e.g. `lines[2].no`), `received` (the value received), `expected` (what was expected) and `nextStep` (what to do now). `hint` says where to read more.\r\nWhen a request has several problems, all of them are listed in `errors[]` - each with the same fields - under a top-level `code` (`MultipleErrors`, or a shared code such as `InvalidLine` for the `lines` of a Create type) and a summary `error`. Fix them all before calling again. One problem is reported at the top level, with no `errors[]`.\r\nRequest values are checked first and every problem found is reported together. A Business Central validation error raised afterwards, while a record is being written, stops the call and is reported on its own: `code` = `BusinessCentralError`, Business Central's own `error` text, and `parameter` naming the request parameter being applied, e.g. `lines[1].accountNo`. Nothing is written.\r\nRequest values are read in one format, whatever the language: dates `YYYY-MM-DD`; date-times ISO 8601 with `Z` or an offset; amounts as JSON numbers (or a string such as `\"1234.56\"`, no thousands separator); integers as JSON integers; booleans `true` or `false`. Any other value is `InvalidParameterFormat` with `received` and `expected`; for an unambiguous local form such as `26.09.2026`, `nextStep` gives the value to resend. Every bad value of a request is reported together.\r\nAnswers are written in one format as well, whatever the language of the call: dates `YYYY-MM-DD`, date-times ISO 8601, numbers with a dot and no thousands separator, and the option and enum values of every answer except `Data.Records.Get` and `Data.Records.Set` as their English names, so a value read from an answer can be sent back. Those two answer the caption of the language of the call, for a person to read. The language of the call (`lcid`) changes captions and message texts, not these forms. Two things are outside Bifrost's control: Business Central writes its own texts (a ledger entry description such as `Direct Cost V00010 on 10/02/26`, the text of a `BusinessCentralError`) with the regional settings of the server session, which `lcid` does not change, so a date in such a text can be in month-day order; and a table view is read with those settings too, so write dates in a view as `YYYY-MM-DD` and decimals with a dot.\r\nBoth success and error responses can carry `warnings[]`, each with `code`, `message` and, when they apply, `parameter` and `nextStep`.\r\n`UnknownParameter` refuses undeclared data keys before execution for every type whose effect is not read, including a missing effect. The root envelope option `strict:false` cannot opt out. Read types keep warnings without changing status, validationResult or domain warningCount unless the caller sets `strict:true` (next to type and subject, never inside data). Refusals list the keys and localized nextStep corrections; no business changes or successful execution charges occur. Example: {\"type\":\"Memory.User.Set\",\"strict\":true,\"data\":{\"memory\":\"test\",\"memry\":\"typo\"}} is refused.\r\n`FieldChangedByBC` is a warning from Data.Records.Set: another field validation or the write changed a sent field after its own validation. `parameter` names data[n].fields.{jsonName}, counting from 0. Status stays Success. Compare the returned values with what you sent; follow `nextStep` to use validation order or send the field again in a separate call. Normalisation of the field itself, LCY, Dimension Set ID, BLOB, Media, MediaSet and skipped fields are excluded.\r\n`SecurityFilterApplied` is a warning from Data.Records.Get, severity `low`, `parameter` `table`: a security filter of the caller applies to the table, so the result may hold fewer records than the table. `securityFiltered` is then true. Status stays Success, and the hidden records are never counted or described. Ask an administrator if you expect more records.\r\nData.RecordIds.Get, Data.Totals.Get, Data.Entries.Find and CSV.Records.Get do not return `securityFiltered` or `SecurityFilterApplied`. Their results can still be limited by security filters: counts and totals cover only visible records, and the absence of a flag or warning does not prove that every record in the table was included. Their help explains this visibility limit; request filters such as tableView and date ranges are separate.\r\nWhen a Business Central operation fails, the error can identify the request parameter being applied, the expected input and what to do next. That guidance accompanies the original `BusinessCentralError` after rollback, including a failed queued task. It does not change which writes are rolled back or committed. Guidance is cleared between messages; a message without it keeps its existing response shape. Recognized lock errors follow the `Retryable` rules below.\r\nSome message types accept calls only through a particular path: a scheduled queue message, the Task API (`/tasks`), the in-product MCP tool server, another message type, or the Messages page Run Task action. Bifrost determines where the call came from; request values cannot override it. A call through an unsupported path is refused with `PreconditionFailed` and a `nextStep` naming the path to use.\r\n`Retryable` means a transient lock or deadlock caught while writing or posting. `error` keeps Business Central's original text. `expected` is \"no concurrent lock on the same records\"; `nextStep` is \"Retry the same call after a few seconds; nothing was changed.\" Bifrost does not retry automatically. Uncaught recognized lock errors are also `Retryable` for `write` types. Uncaught `read` and `irreversible` errors remain `BusinessCentralError`, because an irreversible operation may already have committed.\r\n`ConfirmationRequired` is the preview refusal for an irreversible type called without `expectedCount`. Nothing was changed; inspect `expected` and the description before sending the same request with that count. `ConfirmationMismatch` means the count has changed or the sent count was wrong; nothing was changed. Inspect the new preview before confirming again. Feature apps use the same preview and confirmation protocol for irreversible operations.\r\nCodes: `MissingParameter`, `InvalidParameterFormat`, `InvalidParameter`, `RecordNotFound`, `AmbiguousRecord`, `ConflictingIdentifiers`, `InvalidFilterField`, `InvalidLine`, `NothingToPreview`, `LinesSkipped`, `BlockedByWriteGuard`, `PreconditionFailed`, `PermissionDenied`, `LimitExceeded`, `BusinessCentralError`, `MultipleErrors`, `DeprecatedParameter`, `UnknownParameter`, `FieldChangedByBC`, `Retryable`, `EULA_REQUIRED`, `TRIAL_NOT_STARTED`, `ConfirmationRequired`, `ConfirmationMismatch`, `SecurityFilterApplied`. The `error` text may be translated; the code never is.\r\n"
}
